import subprocess
import os
import time
import glob
def task_func(r_script_path: str, output_path: str, duration: int) -> (bool, str):
    if not isinstance(r_script_path, str) or not isinstance(output_path, str):
        raise TypeError("Invalid input types")
    if not os.path.exists(r_script_path):
        raise OSError("R script path does not exist")
    subprocess.run(['Rscript', r_script_path], shell=True)
    start_time = time.time()
    while time.time() - start_time < duration:
        if glob.glob(output_path):
            return True, 'File generated successfully within the specified duration.'
    return False, 'File not generated within the specified duration.'

import subprocess
from ipaddress import IPv4Network
def task_func(ip_range):
    network = IPv4Network(ip_range)
    active_status = {}
    for ip in network.hosts():
        try:
            subprocess.run(['ping', '-c', '1', '-W', '1', str(ip)], check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            active_status[str(ip)] = True
        except subprocess.CalledProcessError:
            active_status[str(ip)] = False
    return active_status

import subprocess
import platform
import time
def task_func(url):
    if not isinstance(url, str):
        raise TypeError("Invalid URL type")
    if not url:
        raise ValueError("URL cannot be empty")
    system = platform.system()
    if system == "Windows":
        command = f'start {url}'
    elif system == "Darwin":
        command = f'open {url}'
    elif system == "Linux":
        command = f'xdg-open {url}'
    else:
        raise OSError("Unsupported operating system")
    process = subprocess.Popen(command, shell=True)
    time.sleep(1)
    return process.poll()

