import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    src_folder = os.path.abspath(src_folder)
    dst_folder = os.path.abspath(dst_folder)
    if not os.path.exists(src_folder):
        return {'success': False, 'message': 'Source folder does not exist.', 'failed_files': []}
    if not os.path.exists(dst_folder):
        os.makedirs(dst_folder)
    files = glob(os.path.join(src_folder, '*'))
    failed_files = []
    success = True
    for file in files:
        if os.path.isfile(file):
            compressed_file = f"{file}.gz"
            try:
                subprocess.run(['gzip', '-c', file], stdout=open(compressed_file, 'wb'), check=True)
                shutil.move(compressed_file, os.path.join(dst_folder, os.path.basename(compressed_file)))
            except Exception:
                failed_files.append(os.path.basename(file))
                success = False
    message = 'All files compressed and moved successfully.' if success else 'Some files failed to compress or move.'
    return {'success': success, 'message': message, 'failed_files': failed_files}

import subprocess
import os
import sys
import time
def task_func(script_path, wait=True, *args):
    if not os.path.exists(script_path):
        raise ValueError("Script does not exist")
    command = [sys.executable, script_path] + list(args)
    try:
        process = subprocess.Popen(command) if not wait else subprocess.run(command)
        return None if not wait else process.returncode
    except Exception as e:
        raise subprocess.CalledProcessError(returncode=process.returncode if wait else -1, cmd=command)

import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not isinstance(script_path, str):
        raise TypeError("Invalid script path type")
    if not script_path or not os.path.exists(script_path):
        raise OSError("Invalid script path")
    process = subprocess.Popen(['bash', script_path])
    pid = process.pid
    cpu_usage = 0.0
    memory_usage = 0
    start_time = time.time()
    try:
        while time.time() - start_time < timeout:
            if process.poll() is not None:
                break
            proc = psutil.Process(pid)
            cpu_usage += proc.cpu_percent(interval=0.1)
            memory_usage += proc.memory_info().rss
            time.sleep(0.1)
    except (psutil.NoSuchProcess, psutil.ZombieProcess):
        pass
    finally:
        if process.poll() is None:
            process.terminate()
    return {'CPU Usage': cpu_usage, 'Memory Usage': memory_usage}

import subprocess
import pandas as pd
def task_func(script_path, output_file_path):
    result = subprocess.run(['python', script_path], capture_output=True)
    if result.returncode != 0:
        raise ValueError("Script execution failed")
    if not os.path.exists(output_file_path):
        raise ValueError("CSV file not found")
    df = pd.read_csv(output_file_path)
    if df.shape[1] != 2:
        raise ValueError("CSV must contain exactly 2 columns")
    ax = df.plot(kind='bar', x=df.columns[0], y=df.columns[1])
    return df, ax

